-- CoA Character Advancement, server side (catalog + rules from the CoA client DBCs / CoA core docs). Client window: CoAUI addon (Talents.lua).
-- Catalog: coa_talents_data.lua (COA_TREES, COA_BUDGET; generated by tools/coa_ca_lua.py from CharacterAdvancement*.dbc).
-- Rules: Character Advancement unlocks at level 10; the class tree is paid with the class budget (AE), spec trees with the spec budget (TE), 1 point per rank (cumulative per-level
-- budget from CharacterAdvancementEssence.dbc); an entry needs one of its prerequisites learned, the tab gate (points already spent in that tab), its level and one pick per choice group.
-- Automatic entries (cost 0) are granted at level 10+. A held rank = the rank's spell. Changing talents is free (Midnight server choice: retail-like respec).
-- Wire: client -> server COAUI "TAL;<id>" learn next rank | "UNL;<id>" remove one rank | "TRESET" | "TASK";  server -> client COAUI "TS;<level>;<Tab>=<free>,...;<id>:<rank>|..."
if not COA_TREES or not COA_BUDGET or not COA_SLOT_KEY then return end
local PREFIX = "COAUI"
pcall(CharDBExecute, "CREATE TABLE IF NOT EXISTS characters.coa_talent_ranks (guid INT UNSIGNED NOT NULL, entry INT UNSIGNED NOT NULL, `rank` TINYINT UNSIGNED NOT NULL, PRIMARY KEY (guid, entry))")

local byId = {}     -- key -> id -> {node, tab}
for key, tree in pairs(COA_TREES) do
    byId[key] = {}
    for _, t in ipairs(tree.tabs) do for _, n in ipairs(t.nodes) do byId[key][n.id] = {node = n, tab = t} end end
end

local function GL(p) return tostring(p:GetGUIDLow()) end   -- GUIDLow is a uint64 userdata in this Eluna: tostring gives the decimal
local function KeyOf(p) return COA_KEY(p) end

local function Ranks(p)
    local r = {}
    local ok, q = pcall(CharDBQuery, "SELECT entry, `rank` FROM characters.coa_talent_ranks WHERE guid = " .. GL(p))
    if ok and q then repeat r[q:GetUInt32(0)] = q:GetUInt32(1) until not q:NextRow() end
    return r
end
local function SetRank(p, id, rank)
    if rank > 0 then pcall(CharDBExecute, string.format("REPLACE INTO characters.coa_talent_ranks (guid, entry, `rank`) VALUES (%s, %d, %d)", GL(p), id, rank))
    else pcall(CharDBExecute, string.format("DELETE FROM characters.coa_talent_ranks WHERE guid = %s AND entry = %d", GL(p), id)) end
end

local function Budget(p, key, tabName)
    local lvl = p:GetLevel()
    if lvl < 10 then return 0 end
    local b, best = COA_BUDGET[key], nil
    for l in pairs(b) do if l <= lvl and (not best or l > best) then best = l end end
    local v = best and b[best]
    if not v then return 0 end
    return tabName == "Class" and v[1] or v[2]
end

local function Cost(tabName, n) return tabName == "Class" and n.ae or n.te end

local function Spent(key, ranks, tab)
    local s = 0
    for _, n in ipairs(tab.nodes) do s = s + (ranks[n.id] or 0) * Cost(tab.name, n) end
    return s
end

local function Gate(tab, n) return tab.name == "Class" and n.gae or n.gte end

local function Available(key, ranks, tab, n)
    local roots, anyReq = true, false
    for _, r in ipairs(n.req) do
        local e = byId[key][r]
        if e and e.tab == tab then roots = false; if (ranks[r] or 0) > 0 then anyReq = true end end
    end
    if not roots and not anyReq then return false end
    if Gate(tab, n) > Spent(key, ranks, tab) then return false end
    return true
end

local function GrantAuto(p, key)
    local lvl = p:GetLevel()
    if lvl < 10 then return end
    for _, tab in ipairs(COA_TREES[key].tabs) do
        for _, n in ipairs(tab.nodes) do
            if tab.name == "Class" and n.auto == 1 and n.lvl <= lvl then   -- ponytail: spec-tab automatic passives need the active spec (not tracked yet), so only the shared class tab is granted
                for _, s in ipairs(n.ranks) do if not p:HasSpell(s) then p:LearnSpell(s) end end
            end
        end
    end
end

local function Send(p)
    local key = KeyOf(p)
    if not key then return end
    local ranks = Ranks(p)
    GrantAuto(p, key)
    local free, ent = {}, {}
    for _, tab in ipairs(COA_TREES[key].tabs) do free[#free + 1] = tab.name .. "=" .. math.max(0, Budget(p, key, tab.name) - Spent(key, ranks, tab)) end
    for id, r in pairs(ranks) do ent[#ent + 1] = id .. ":" .. r end
    pcall(function() p:SendAddonMessage(PREFIX, string.format("TS;%d;%s;%s", p:GetLevel(), table.concat(free, ","), table.concat(ent, "|")), 7, p) end)
end

local function Learn(p, id)
    local key = KeyOf(p)
    local e = key and byId[key][id]
    if not e or e.node.auto == 1 then return end
    local n, tab = e.node, e.tab
    local ranks = Ranks(p)
    local cur = ranks[id] or 0
    local function no(msg) p:SendBroadcastMessage("|cffff8000[Talents]|r " .. msg) end
    if p:GetLevel() < 10 then return no("Character Advancement unlocks at level 10.") end
    if cur >= #n.ranks then return end
    if n.lvl > p:GetLevel() then return no("Requires level " .. n.lvl .. ".") end
    if Budget(p, key, tab.name) - Spent(key, ranks, tab) < Cost(tab.name, n) then return no("No points left in this tree.") end
    if cur == 0 then
        if not Available(key, ranks, tab, n) then return no("Learn a connected talent first, or spend more points in this tree.") end
        if n.grp ~= 0 then
            for _, o in ipairs(tab.nodes) do if o.id ~= id and o.grp == n.grp and (ranks[o.id] or 0) > 0 then return no("You already chose another option.") end end
        end
    end
    if cur > 0 and n.ranks[cur] and p:HasSpell(n.ranks[cur]) then p:RemoveSpell(n.ranks[cur]) end
    local s = n.ranks[cur + 1]
    if s and not p:HasSpell(s) then p:LearnSpell(s) end
    SetRank(p, id, cur + 1)
end

local function Unlearn(p, id)
    local key = KeyOf(p)
    local e = key and byId[key][id]
    if not e or e.node.auto == 1 then return end
    local n, tab = e.node, e.tab
    local ranks = Ranks(p)
    local cur = ranks[id] or 0
    if cur == 0 then return end
    ranks[id] = cur - 1
    for _, o in ipairs(tab.nodes) do          -- everything learned must stay available (prerequisites and gates)
        if (ranks[o.id] or 0) > 0 and o.id ~= id then
            local saved = ranks[o.id]; ranks[o.id] = 0
            local ok = Available(key, ranks, tab, o)
            ranks[o.id] = saved
            if not ok then p:SendBroadcastMessage("|cffff8000[Talents]|r Other talents depend on this one."); return end
        end
    end
    if n.ranks[cur] and p:HasSpell(n.ranks[cur]) then p:RemoveSpell(n.ranks[cur]) end
    if cur - 1 > 0 and n.ranks[cur - 1] then p:LearnSpell(n.ranks[cur - 1]) end
    SetRank(p, id, cur - 1)
end

local function Reset(p)
    local key = KeyOf(p)
    if not key then return end
    for id in pairs(Ranks(p)) do
        local e = byId[key][id]
        if e and e.node.auto ~= 1 then for _, s in ipairs(e.node.ranks) do if p:HasSpell(s) then p:RemoveSpell(s) end end end
    end
    pcall(CharDBExecute, "DELETE FROM characters.coa_talent_ranks WHERE guid = " .. GL(p))
end

RegisterServerEvent(30, function(_, sender, msgType, prefix, msg)
    if prefix ~= PREFIX then return end
    local ok, isPlayer = pcall(function() return sender:GetGUIDLow() ~= nil and sender.LearnSpell ~= nil end)
    if not ok or not isPlayer or not KeyOf(sender) then return end
    local kind, arg = (msg or ""):match("^(%u+);?(%d*)")
    if kind == "TAL" then Learn(sender, tonumber(arg)) elseif kind == "UNL" then Unlearn(sender, tonumber(arg)) elseif kind == "TRESET" then Reset(sender) end
    if kind == "TAL" or kind == "UNL" or kind == "TRESET" or kind == "TASK" then
        local guid = sender:GetGUID()
        CreateLuaEvent(function() local p = GetPlayerByGUID(guid); if p and p:IsInWorld() then Send(p) end end, 300, 1)   -- after the DB write
    end
end)
print("[coa_talents] loaded (exact CoA catalog)")
